<span class="line"><span style="color:#E5C07B;">cmd</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">CommandType</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> CommandType</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">StoredProcedure</span><span style="color:#ABB2BF;">;</span></span>
